            "INSERT INTO asset_tag(asset_id, tag, position) VALUES (?, ?, ?)",
            [(asset_id, tag, position) for position, tag in enumerate(tags)],
        )
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
