        if isinstance(exc, sqlite3.IntegrityError) and _path_registered(
            conn, canonical_path
        ):
            raise CliError(f"素材已登记，拒绝重复登记: {canonical_path}")
        raise CliError(f"数据库写入失败: {exc}")
finally:
    conn.close()

